lug":"pisa","university_name":"University of Pisa","programme_name":"Engineering of paper and cardboard","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":"WTC-LM","degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/engineering-of-paper-and-cardboard-wep-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"cb1795a2fdb236b2"},{"university_slug":"pisa","university_name":"University of Pisa","programme_name":"Exploration and Applied Geophysics","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":"WGF-LM","degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/exploration-and-applied-geophysics-wagr-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"d62eb42a6bdc1ef4"},{"university_slug":"pisa","university_name":"University of Pisa","programme_name":"Informatics for digital health","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":null,"degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/informatics-for-digital-health-wdh-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"f7dc71ac7d3c0e81"},{"university_slug":"pisa","university_name":"University of Pisa","programme_name":"Materials and Nanotechnology","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":"WNT-LM","degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/materials-and-nanotechnology-wnn-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"d678acfa1cf43f0f"},{"university_slug":"pisa","university_name":"University of Pisa","programme_name":"Neuroscience","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":"WNC-LM","degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/neuroscience-wncr-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"ce1f5d1b6786aa3d"},{"university_slug":"pisa","university_name":"University of Pisa","programme_name":"Nuclear Engineering","city":"Pisa","degree_level":"Master","teaching_language":"English","official_programme_code":"WSN-LM","degree_class":null,"duration_years":2.0,"source_url":"https://www.unipi.it/en/education/courses/master-degree/nuclear-engineering-wsnr-lm-en/","catalogue_source_url":"https://www.unipi.it/en/international-students/programmes-taught-in-english/degree-programmes-held-in-english/","academic_year":"2026/27","content_hash":"d7299c8c708281a7"}]$catalogue$::jsonb) as row(
    university_slug text,
    university_name text,
    programme_name text,
    city text,
    degree_level text,
    teaching_language text,
    official_programme_code text,
    degree_class text,
    duration_years numeric,
    source_url text,
    catalogue_source_url text,
    academic_year text,
    content_hash text
  )
), resolved as (
  select incoming.*, universities.id as university_id
  from incoming
  join public.universities on universities.slug = incoming.university_slug
), updated as (
  update public.programmes as programme
  set
    university_id = resolved.university_id,
    university_name = resolved.university_name,
    programme_name = resolved.programme_name,
    city = resolved.city,
    degree_level = resolved.degree_level,
    teaching_language = resolved.teaching_language,
    official_programme_code = coalesce(resolved.official_programme_code, programme.official_programme_code),
    degree_class = coalesce(resolved.degree_class, programme.degree_class),
    duration_years = coalesce(resolved.duration_years, programme.duration_years),
    catalogue_source_url = resolved.catalogue_source_url,
    catalogue_checked_at = date '2026-09-24',
    updated_at = now()
  from resolved
  where programme.academic_year = resolved.academic_year
    and programme.university_id = resolved.university_id
    and (
      (resolved.official_programme_code is not null
        and programme.official_programme_code = resolved.official_programme_code)
      or (lower(programme.programme_name) = lower(resolved.programme_name)
        and programme.degree_level = resolved.degree_level)
    )
  returning programme.id
)
insert into public.programmes (
  university_id, university_name, programme_name, country_code, city,
  degree_level, teaching_language, intake, source_url, application_url,
  academic_year, verification_status, verification_notes, requirements,
  official_programme_code, degree_class, catalogue_source_url,
  catalogue_checked_at, duration_years
)
select
  resolved.university_id,
  resolved.university_name,
  resolved.programme_name,
  'IT',
  resolved.city,
  resolved.degree_level,
  resolved.teaching_language,
  'Fall 2026',
  resolved.source_url,
  resolved.source_url,
  resolved.academic_year,
  'unverified',
  'Discovered in an official university catalogue. Admission requirements, fees, and deadlines require human verification.',
  '{}'::jsonb,
  resolved.official_programme_code,
  resolved.degree_class,
  resolved.catalogue_source_url,
  date '2026-09-24',
  resolved.duration_years
from resolved
where not exists (
  select 1
  from public.programmes as existing
  where existing.university_id = resolved.university_id
    and existing.academic_year = resolved.academic_year
    and (
      (resolved.official_programme_code is not null
        and existing.official_programme_code = resolved.official_programme_code)
      or (lower(existing.programme_name) = lower(resolved.programme_name)
        and existing.degree_level = resolved.degree_level)
    )
)
on conflict (university_name, programme_name, academic_year, degree_level) do nothing;
